import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:kestrel_rns/kestrel_rns.dart';

/// Loads `test/vectors/<name>` (generated by `tools/gen_vectors.py`).
Map<String, Object?> loadVectors(String name) {
  final f = File('test/vectors/$name');
  return json.decode(f.readAsStringSync()) as Map<String, Object?>;
}

Uint8List unhex(String? s) {
  if (s == null || s.isEmpty) return Uint8List(0);
  final out = Uint8List(s.length ~/ 2);
  for (var i = 0; i < out.length; i++) {
    out[i] = int.parse(s.substring(2 * i, 2 * i + 2), radix: 16);
  }
  return out;
}

String hex(List<int> b) =>
    b.map((e) => e.toRadixString(16).padLeft(2, '0')).join();

List<Map<String, Object?>> maps(Object? v) =>
    (v! as List<Object?>).cast<Map<String, Object?>>();

Map<String, Object?> asMap(Object? v) => v! as Map<String, Object?>;

/// Converts a typed vector tree (see gen_vectors.to_tree) into a Dart value.
Object? fromTree(Object? node) {
  final n = node! as Map<String, Object?>;
  switch (n['type']) {
    case 'nil':
      return null;
    case 'bool':
      return n['value'];
    case 'int':
      final v = BigInt.parse(n['value']! as String);
      return v.isValidInt ? v.toInt() : v;
    case 'float':
      return floatFromBits(n['bits']! as String);
    case 'str':
      return n['value'];
    case 'bin':
      return unhex(n['hex'] as String?);
    case 'array':
      return (n['items']! as List<Object?>).map(fromTree).toList();
    case 'map':
      final m = <Object?, Object?>{};
      for (final e in (n['entries']! as List<Object?>).cast<List<Object?>>()) {
        m[fromTree(e[0])] = fromTree(e[1]);
      }
      return m;
  }
  throw StateError('bad tree $n');
}

/// Structural equality that distinguishes int/double, bin/str and compares
/// bytes by value and doubles by bit pattern (NaN-safe).
bool deepEquals(Object? a, Object? b) {
  if (a == null || b == null) return a == null && b == null;
  if (a is Uint8List && b is Uint8List) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) return false;
    }
    return true;
  }
  if (a is double && b is double) {
    return (ByteData(8)..setFloat64(0, a)).getInt64(0) ==
        (ByteData(8)..setFloat64(0, b)).getInt64(0);
  }
  if (a is List<Object?> && b is List<Object?>) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (!deepEquals(a[i], b[i])) return false;
    }
    return true;
  }
  if (a is Map<Object?, Object?> && b is Map<Object?, Object?>) {
    if (a.length != b.length) return false;
    final ea = a.entries.toList();
    final eb = b.entries.toList();
    for (var i = 0; i < ea.length; i++) {
      if (!deepEquals(ea[i].key, eb[i].key) ||
          !deepEquals(ea[i].value, eb[i].value)) {
        return false;
      }
    }
    return true;
  }
  return a.runtimeType == b.runtimeType && a == b;
}

/// Loads the identity records of a vector file into [Identity] objects.
Future<Map<String, Identity>> loadIdentities(
    List<Map<String, Object?>> recs) async {
  final out = <String, Identity>{};
  for (final r in recs) {
    out[r['name']! as String] =
        await Identity.fromPrivateKey(unhex(r['private_key'] as String?));
  }
  return out;
}

/// Decodes a big-endian float64 bit pattern given as 16 hex digits.
double floatFromBits(String bits) {
  final b = unhex(bits);
  return ByteData.sublistView(b).getFloat64(0);
}
